function jsonSource(buf: Buffer, input: string): Source {
  let data: unknown;
  try {
    data = JSON.parse(decodeUtf8(buf));
  } catch (e) {
    if (e instanceof Fatal) throw e;
    throw new Fatal("invalid JSON");
