      if (line === "") return;
      const loc = `${input}:${k + 1}`;
      let v: unknown;
      try {
        v = JSON.parse(line);
      } catch {
        rows.push({ loc, bad: "invalid JSON", get: () => EMPTY });
        return;
      }
      rows.push(objectRow(loc, v));
